using System.Collections;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ForcefulStreamEffect", menuName = "Data/Battle/Effects/Cellarius/ForcefulStream Effect")]
public class ForcefulStreamEffect : Effect
{
	[Header("Action Specifics")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private int corruptAmount;

	[Header("Description")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private CorruptAction corruptAction;

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return Smart.Format(localizedDescription, base.localizationManager.GetLocalizedAtTheEndOfYourTurn(), corruptAction.GetActionDescription(corruptAmount).RemoveLast(), purifyAction.GetActionDescription(-1));
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return Smart.Format(GetLocalizedDescription(), base.localizationManager.GetLocalizedAtTheEndOfYourTurn(), corruptAction.GetActionDescription(corruptAmount).RemoveLast(), purifyAction.GetActionDescription(amount));
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAfflictionReliefHealbotForcefulStreamAction(ForcefulStreamCoroutine(effectAmount, effectOwner));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		return effectAmount;
	}

	private IEnumerator ForcefulStreamCoroutine(int effectAmount, GameObject effectOwner)
	{
		bool vfxEnabled = IsVFXEnabled();
		yield return new WaitForSeconds(vfxEnabled ? 0.3f : 0.2f);
		if (vfxEnabled)
		{
			PlayEffectActivationSFX();
		}
		SpawnVFXOnPlayerPosition(3f);
		effectOwner.GetComponent<PlayerCorruptionStats>().Corrupt(corruptAmount, null, CorruptionPurifyModifierEnum.FORCEFULSTREAM, !vfxEnabled);
		for (int i = 0; i < currentCorruptedAnimals.activeCorruptedAnimals.Count; i++)
		{
			currentCorruptedAnimals.activeCorruptedAnimals[i].GetComponent<CorruptedAnimalCorruptionStats>().Purify(effectAmount, null, !vfxEnabled);
		}
		yield return new WaitForSeconds(vfxEnabled ? 0.8f : 0.6f);
	}
}
